for line in DATA.strip().splitlines():
 parts=line.split('|')
 if len(parts)!=7:raise Exception((len(parts),line))
 add(*parts)
print('Core authored questions:',len(Q))
# Make ten non-identical balanced examinations, rotating base questions and giving each a distinct applied lead-in.
contexts=[
 'A California applicant is reviewing life insurance concepts.',
 'A prospective policyowner asks an insurance producer for guidance.',
 'During a California licensing practice interview, a candidate is questioned.',
 'An agent is discussing a possible life insurance purchase with a client.',
 'A consumer is comparing a policy proposal with their financial goals.',
 'During an insurance training session, a producer considers this situation.',
 'A policyowner is evaluating benefits and limitations of coverage.',
 'A client wants to understand an insurance contract before signing.',
 'In a prelicensing classroom, a learner considers a customer scenario.',
 'A California life agent is asked to explain the following concept.'
]
# Shuffle base question selection such that recurring concepts get varied contextual versions.
bycat={}
for i,q in enumerate(Q):bycat.setdefault(q['category'],[]).append(i)
print({k:len(v) for k,v in bycat.items()})
# Each exam includes a representation across categories, with 75 total and unique question IDs.
weights={'Fundamentals':11,'Term & Whole Life':17,'Provisions & Riders':16,'Annuities & Retirement':10,'Underwriting & Claims':9,'Ethics & CA Law':8,'Business & Tax':4}
assert sum(weights.values())==75
exams=[]
for exam in range(10):
 chosen=[]
 for cat,n in weights.items():
  arr=bycat[cat];rng=random.Random(4781+exam*19+len(cat));order=arr.copy();rng.shuffle(order)
  # select rotating item sets for broad total coverage
  start=(exam*max(1,n//2))%len(order)
  chosen.extend((order*3)[start:start+n])
 rng=random.Random(2000+exam);rng.shuffle(chosen)
 items=[]
 for position,qi in enumerate(chosen):
  q=Q[qi].copy()
  # Reword stem with context, and vary answer position deterministically.
  lead=contexts[(exam+position*3)%len(contexts)]
  q['stem']=lead+' '+q['stem']
  perm=list(range(4));random.Random(7000+exam*1000+position).shuffle(perm)
  q['options']=[q['options'][x] for x in perm]
  q['answer']=perm.index(0)
  q['id']=f'E{exam+1:02}Q{position+1:02}'
  items.append(q)
 exams.append({'title':f'Exam {exam+1}', 'questions':items})
assert len(exams)==10 and all(len(e['questions'])==75 for e in exams)
(P/'questions.json').write_text(json.dumps(exams,ensure_ascii=False,indent=1),encoding='utf8')
# javascript embed for file:// convenience, no server needed.
(P/'questions.js').write_text('window.EXAMS = '+json.dumps(exams,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf8')
